def test_perfect():
    assert solution.hinge_loss([2.0, -3.0], [1, -1]) == 0.0

def test_basic():
    got = solution.hinge_loss([1.0, 0.5, -0.5], [1, 1, -1])
    assert abs(got - 1.0 / 3.0) < 1e-9

def test_length_mismatch():
    try:
        solution.hinge_loss([1.0], [1, -1])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_bad_label():
    try:
        solution.hinge_loss([1.0], [0])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_empty():
    assert solution.hinge_loss([], []) == 0.0

def test_all_inside_margin():
    assert solution.hinge_loss([0.0, 0.0], [1, -1]) == 1.0
